          values (NEW.id, 'RELEASE_OPEN_COMPLETED', 'UPDATE', OLD.RELEASE_OPEN_COMPLETED, NEW.RELEASE_OPEN_COMPLETED, statement_timestamp(), l_changed_by);
       end if;
