DROP TRIGGER IF EXISTS sp_team_members_biu ON sp_team_members CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_team_members_biu() RETURNS trigger AS $BODY$
declare
    b numeric := 0; -- first dot occurrance
    e numeric := 0; -- first at sign occurrance
    l numeric := 0; -- length between dot and at sign
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    NEW.email := lower(NEW.email);
    --
    NEW.screen_name := lower(NEW.screen_name);
    --
    if coalesce(NEW.is_current_yn::text, '') = '' then
       NEW.is_current_yn := 'Y';
    end if;
    b := position('.' in NEW.email);
    e := position('@' in NEW.email);
    --
    NEW.email_domain := substr(NEW.email,e+1);
    --
    if e > 2 and b > 1 and coalesce(NEW.first_name::text, '') = '' and coalesce(NEW.last_name::text, '') = '' then
       l := (e - b) - 1;
       if b < e and l > 0 then
           NEW.first_name := initcap(substr(NEW.email,1,b-1));
           NEW.last_name  := initcap(substr(NEW.email,b+1,l));
       end if;
    end if;
    if coalesce(NEW.initials::text, '') = '' and (NEW.first_name IS NOT NULL AND NEW.first_name::text <> '') and (NEW.last_name IS NOT NULL AND NEW.last_name::text <> '') then
        NEW.initials := coalesce(substr(NEW.first_name,1,1)||substr(NEW.last_name,1,1),'X');
    end if;
    if coalesce(NEW.initials::text, '') = '' then
       NEW.initials := 'AA';
    end if;
    if coalesce(NEW.first_name::text, '') = '' then
       NEW.first_name := 'unknown';
    end if;
    if coalesce(NEW.last_name::text, '') = '' then
       NEW.last_name := 'unknown';
    end if;
    --
    -- tags
    --
    NEW.tags := upper(NEW.tags);

RETURN NEW;
end
$BODY$
 LANGUAGE 'plpgsql';

