DROP TRIGGER IF EXISTS sp_initiatives_biu ON sp_initiatives CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_initiatives_biu() RETURNS trigger AS $BODY$
DECLARE
  c1 RECORD;
    l_tags        varchar(4000);
    l_old_value   varchar(4000) := null;
    l_new_value   varchar(4000) := null;
    l_changed_by  varchar(255)  := null;
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    if coalesce(NEW.SPONSOR_ID::text, '') = '' then
       for c1 in (SELECT OWNER_ID from SP_AREAS f where f.id = NEW.AREA_ID and (owner_id IS NOT NULL AND owner_id::text <> '') ) loop
           NEW.SPONSOR_ID := c1.owner_id;
       end loop;
    end if;
    --
    -- short ID used as an alternative to long numeric ID primary key column
    --
    if coalesce(NEW.friendly_identifier::text, '') = '' then
       NEW.friendly_identifier := sp_util.compress_int(nextval('sp_seq'));
    end if;
    --
    -- used to provide friendly URLs
    --
    if not sp_value_compare.is_equal(OLD.initiative,NEW.initiative) then
       NEW.initiative_url_name := ltrim(rtrim(replace(replace(REGEXP_REPLACE(translate(substr(NEW.initiative,1,80),'()+%$&^!@[];:"?/~!-+_.<>','                        '),'\s+', ' ', 'g'), '''', ''),' ','-'),'-'),'-');
    end if;
    --
    -- status scale
    --
    if coalesce(NEW.status_scale::text, '') = '' then
       NEW.status_scale := 'A';
    end if;
    --
    -- adjust tag data
    --
    if (NEW.tags IS NOT NULL AND NEW.tags::text <> '') then
        l_tags := trim(both upper(NEW.tags));
        -- remove multiple spaces
        if position('  ' in l_tags) > 0 then
            for j in 1..10 loop
                l_tags := replace(l_tags,'  ',' ');
                if position('  ' in l_tags) = 0 then
                   exit;
                end if;
            end loop;
        end if;
        for i in 1..length(l_tags) loop
            if i > 2 and substr(l_tags,i,1) = ' ' and substr(l_tags,i-1,1) != ',' then
               l_tags := substr(l_tags,1,i-1)||'-'||substr(l_tags,i+1);
            end if;
        end loop;
        NEW.tags := l_tags;
   end if;
   --
   --
   --
   if coalesce(NEW.hidden_by_default_yn::text, '') = '' then
      NEW.hidden_by_default_yn := 'N';
   end if;
   --
   -- touch parent table
   --
   update sp_areas set updated = statement_timestamp(), updated_by = NEW.updated_by where id = NEW.area_id;
    --
    -- history
    --
    if TG_OP = 'UPDATE' then
        l_changed_by := lower(NEW.updated_by);

        if not sp_value_compare.is_equal(OLD.initiative,NEW.initiative) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'INITIATIVE', 'UPDATE', OLD.initiative, NEW.initiative, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.area_id,NEW.area_id) then
            for c1 in (SELECT AREA r from SP_AREAS x where x.id = OLD.AREA_ID) loop l_old_value := c1.r;end loop;
            for c1 in (SELECT AREA r from SP_AREAS x where x.id = NEW.AREA_ID) loop l_new_value := c1.r;end loop;
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'AREA', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.objective,NEW.objective) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'OBJECTIVE', 'UPDATE', OLD.objective, NEW.objective, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.sponsor_id,NEW.sponsor_id) then
            for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = OLD.sponsor_id) loop l_old_value := c1.r;end loop;
            for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = NEW.sponsor_id) loop l_new_value := c1.r;end loop;
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'SPONSOR', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.status_scale,NEW.status_scale) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'STATUS_SCALE', 'UPDATE', OLD.status_scale, NEW.status_scale, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.tags,NEW.tags) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (NEW.id, 'TAGS', 'UPDATE', OLD.tags, NEW.tags, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.archived_yn,NEW.archived_yn) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
            values (NEW.id, 'ARCHIVED', 'UPDATE', OLD.archived_yn, NEW.archived_yn, statement_timestamp(), l_changed_by);
        end if;
        if not sp_value_compare.is_equal(OLD.hidden_by_default_yn,NEW.hidden_by_default_yn) then
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
            values (NEW.id, 'HIDDEN_BY_DEFAULT', 'UPDATE', OLD.hidden_by_default_yn, NEW.hidden_by_default_yn, statement_timestamp(), l_changed_by);
        end if;
    end if;
RETURN NEW;
end
