DROP TRIGGER IF EXISTS sp_project_contributors_biu ON sp_project_contributors CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_project_contributors_biu() RETURNS trigger AS $BODY$
DECLARE
  c1 RECORD;
    l_old_value   varchar(4000) := null;
    l_new_value   varchar(4000) := null;
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    NEW.tags := trim(both upper(NEW.tags));
    --
    -- touch parent table
    --
    update sp_projects set updated = statement_timestamp(), updated_by = NEW.updated_by where id = NEW.project_id;
    --
    -- history
    --
    if TG_OP = 'INSERT' then
          for c1 in (SELECT first_name||' '||last_name||' - '||email x from SP_TEAM_MEMBERS t where t.id = NEW.TEAM_MEMBER_ID) loop l_new_value := c1.x;end loop;
          for c1 in (SELECT resource_type x from SP_RESOURCE_TYPES t where t.id = NEW.RESPONSIBILITY_ID) loop l_new_value := l_new_value||' - '||c1.x;end loop;
        insert into sp_project_history(project_id, attribute_column, change_type, new_value, changed_on, changed_by)
        values (NEW.project_id, 'CONTRIBUTOR', 'CREATE', l_new_value, statement_timestamp(), lower(NEW.created_by));
    elsif TG_OP = 'UPDATE' then
          for c1 in (SELECT first_name||' '||last_name||' - '||email x from SP_TEAM_MEMBERS t where t.id = OLD.TEAM_MEMBER_ID) loop l_old_value := c1.x;end loop;
          for c1 in (SELECT first_name||' '||last_name||' - '||email x from SP_TEAM_MEMBERS t where t.id = NEW.TEAM_MEMBER_ID) loop l_new_value := c1.x;end loop;
          for c1 in (SELECT resource_type x from SP_RESOURCE_TYPES t where t.id = OLD.RESPONSIBILITY_ID) loop l_old_value := l_old_value||' - '||c1.x;end loop;
          for c1 in (SELECT resource_type x from SP_RESOURCE_TYPES t where t.id = NEW.RESPONSIBILITY_ID) loop l_new_value := l_new_value||' - '||c1.x;end loop;
          --
          -- only log updates that change values
          --
          if coalesce(l_old_value,'x') != coalesce(l_new_value,'x') then
              insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
              values (NEW.project_id, 'CONTRIBUTOR', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), lower(NEW.updated_by));
          end if;
    end if;

RETURN NEW;
end
$BODY$
 LANGUAGE 'plpgsql';

