    --
    -- touch parent table
    --
    update sp_projects set updated = statement_timestamp(), updated_by = OLD.updated_by where id = OLD.project_id;
    --
    for c1 in (SELECT email from sp_team_members x where x.id = OLD.team_member_id) loop
        v1 := c1.email;
    end loop;
    for c1 in (SELECT resource_type from sp_resource_types x where x.id = OLD.responsibility_id) loop
        v2 := c1.resource_type;
    end loop;
    insert into sp_project_history(project_id, attribute_column, change_type, old_value, changed_on, changed_by)
    values (OLD.project_id, 'CONTRIBUTOR', 'DELETE', v2||': '||v1, statement_timestamp(), lower(coalesce(sys_context('APEX$SESSION','APP_USER'),user)));
RETURN OLD;
end
$BODY$
 LANGUAGE 'plpgsql';

