	before insert or update ON sp_project_related FOR EACH ROW
	EXECUTE PROCEDURE legacy.trigger_fct_sp_project_related_biu();

-- Generated by Ora2Pg, the Oracle database Schema converter, version 25.0
-- Copyright 2000-2025 Gilles DAROLD. All rights reserved.
-- DATASOURCE: dbi:Oracle:host=localhost;sid=NONE

SET client_encoding TO 'UTF8';

SET search_path = legacy,public;
\set ON_ERROR_STOP ON

SET check_function_bodies = false;

DROP TRIGGER IF EXISTS sp_projects_biu ON sp_projects CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_projects_biu() RETURNS trigger AS $BODY$
DECLARE
  c1 RECORD;
    l_old_value   varchar(4000) := null;
    l_new_value   varchar(4000) := null;
    l_changed_by  varchar(255)  := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    l_old_clob    text;
    l_new_clob    text;
    l_tags        varchar(4000) := null;
BEGIN
    --
    -- maintain tracking columns
    --
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := l_changed_by;
    end if;
    if sp_globals.g_audit_this then
        NEW.updated := statement_timestamp();
        NEW.updated_by := l_changed_by;
    end if;
    --
    -- upper project name
    --
    NEW.upper_project_name := upper(NEW.project);

    --
    -- set external_ticket_identifier and EXTERNAL_TICKET_SYSTEM and external_system_link
    --
    NEW.external_ticket_system     := null;
    NEW.external_ticket_identifier := null;
    NEW.external_system_link       := null;
    for c1 in (
        SELECT EXTERNAL_SYSTEM_NAME,
               LINK_PATTERN, 
               TICKET_ID_REGEX,
               REQUIRED_INITIATIVE_ID,
               replace(replace(replace(replace((SELECT array_to_string(a, '') FROM regexp_matches(NEW.project, ticket_id_regex, 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) ),':','-'),' ','-'),'<','-'),'>','-') ext_id
          from SP_EXTERNAL_TICKETING_SYSTEMS
         where coalesce(IS_ACTIVE_YN,'N') = 'Y'
           and (SELECT array_to_string(a, '') FROM regexp_matches(NEW.project, ticket_id_regex, 'g') AS foo(a) LIMIT 1 OFFSET (1 - 1) ) is not null
           and (coalesce(required_initiative_id::text, '') = '' or required_initiative_id = NEW.initiative_id) 
         order by evaulation_sequence
    ) loop
           NEW.EXTERNAL_TICKET_SYSTEM := c1.EXTERNAL_SYSTEM_NAME;
           if position('#TICKET_NUMERIC#' in c1.LINK_PATTERN) > 0 then
              NEW.external_ticket_identifier := c1.ext_id;
              NEW.external_system_link       := replace(c1.LINK_PATTERN,'#TICKET_NUMERIC#',regexp_replace(c1.ext_id,'[^0-9]','', 'g'));
           elsif position('#TICKET#' in c1.LINK_PATTERN) > 0 then
              NEW.external_ticket_identifier := c1.ext_id;
              NEW.external_system_link       := replace(c1.LINK_PATTERN,'#TICKET#',NEW.external_ticket_identifier);
           else
              NEW.external_ticket_identifier := null;
              NEW.external_system_link       := c1.LINK_PATTERN;
           end if;
           exit;
    end loop;

    --
    -- adjust tag data
    --
    if (NEW.tags IS NOT NULL AND NEW.tags::text <> '') then
        l_tags := trim(both upper(NEW.tags));
        -- remove multiple spaces
        if position('  ' in l_tags) > 0 then
            for j in 1..10 loop
                l_tags := replace(l_tags,'  ',' ');
                if position('  ' in l_tags) = 0 then
                   exit;
                end if;
            end loop;
        end if;
        for i in 1..length(l_tags) loop
            if i > 2 and substr(l_tags,i,1) = ' ' and substr(l_tags,i-1,1) != ',' then
               l_tags := substr(l_tags,1,i-1)||'-'||substr(l_tags,i+1);
            end if;
        end loop;
        NEW.tags := l_tags;
   end if;

    --
    -- defaults
    --
    if coalesce(NEW.STATUS_SCALE::text, '') = '' then
       NEW.STATUS_SCALE := 'A';
    end if;
    --
    if coalesce(NEW.ARCHIVED_YN::text, '') = '' then
       NEW.ARCHIVED_YN := 'N';
    end if;
    --
    -- short project ID used as an alturnative to long numeric ID primary key column
    --
    if coalesce(NEW.friendly_identifier::text, '') = '' then
       NEW.friendly_identifier := sp_util.compress_int(nextval('sp_seq'));
    end if;
    --
    -- used to provide friendly URLs
    --
    if not sp_value_compare.is_equal(OLD.project,NEW.project) then
       NEW.project_url_name := ltrim(rtrim(replace(replace(REGEXP_REPLACE(translate(substr(NEW.project,1,80),'()+%$&^!@[];:"?/~!-+_.<>','                        '),'\s+', ' ', 'g'), '''', ''),' ','-'),'-'),'-');
    end if;

    --
    -- change history tracking
    --
    if TG_OP = 'UPDATE' then
       l_changed_by := lower(l_changed_by);
       --
       -- INITIATIVE_ID
       --
       if not sp_value_compare.is_equal(OLD.INITIATIVE_ID,NEW.INITIATIVE_ID) then
          for c1 in (SELECT INITIATIVE r from SP_INITIATIVES x where x.id = OLD.INITIATIVE_ID) loop l_old_value := c1.r;end loop;
          for c1 in (SELECT INITIATIVE r from SP_INITIATIVES x where x.id = NEW.INITIATIVE_ID) loop l_new_value := c1.r;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'INITIATIVE', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       --
       -- PROJECT 
       --
       if not sp_value_compare.is_equal(OLD.PROJECT,NEW.PROJECT) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'PROJECT', 'UPDATE', OLD.PROJECT, NEW.PROJECT, statement_timestamp(), l_changed_by);
       end if;
       --
       -- DESCRIPTION 
       --
       if not sp_value_compare.is_equal(OLD.DESCRIPTION,NEW.DESCRIPTION) then
          l_old_clob := OLD.DESCRIPTION;
          l_new_clob := NEW.DESCRIPTION;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, old_value_clob, new_value_clob, changed_on, changed_by)
          values (NEW.id, 'DESCRIPTION', 'UPDATE', substr(OLD.DESCRIPTION, 1, 500), substr(NEW.DESCRIPTION, 1, 500), l_old_clob, l_new_clob, statement_timestamp(), l_changed_by);
       end if;
       --
       -- OWNER_ID
       --
       if not sp_value_compare.is_equal(OLD.OWNER_ID,NEW.OWNER_ID) then
          for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = OLD.owner_id) loop l_old_value := c1.r;end loop;
          for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = NEW.owner_id) loop l_new_value := c1.r;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'OWNER', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       --
       -- TARGET_COMPLETE
       --
       if not sp_value_compare.is_equal(OLD.TARGET_COMPLETE,NEW.TARGET_COMPLETE) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'TARGET_COMPLETE', 'UPDATE', to_char(OLD.TARGET_COMPLETE,'DD-MON-YYYY'), to_char(NEW.TARGET_COMPLETE,'DD-MON-YYYY'), statement_timestamp(), l_changed_by);
       end if;
       --
       -- STATUS_SCALE
       --
       if not sp_value_compare.is_equal(OLD.status_scale,NEW.status_scale) then
          for c1 in (SELECT scale_name from sp_project_scales where OLD.status_scale = scale_letter) loop l_old_value := c1.scale_name;end loop;
          for c1 in (SELECT scale_name from sp_project_scales where NEW.status_scale = scale_letter) loop l_new_value := c1.scale_name;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'STATUS_SCALE', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       --
       -- PCT_COMPLETE
       --
       if not sp_value_compare.is_equal(OLD.pct_complete,NEW.pct_complete) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'PCT_COMPLETE', 'UPDATE', OLD.pct_complete, NEW.pct_complete, statement_timestamp(), l_changed_by);
       end if;
       -- STATUS
       if not sp_value_compare.is_equal(OLD.status_id,NEW.status_id) then
          for c1 in (SELECT status from sp_project_statuses where OLD.status_id = id) loop l_old_value := c1.status;end loop;
          for c1 in (SELECT status from sp_project_statuses where NEW.status_id = id) loop l_new_value := c1.status;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'STATUS', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       -- REQUIRES_REVIEWS_YN
       if not sp_value_compare.is_equal(OLD.requires_reviews_yn,NEW.requires_reviews_yn) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'REQUIRES_REVIEWS', 'UPDATE', OLD.requires_reviews_yn, NEW.requires_reviews_yn, statement_timestamp(), l_changed_by);
       end if;
       -- DUPLICATE_OF_PROJECT_ID
       if not sp_value_compare.is_equal(OLD.duplicate_of_project_id,NEW.duplicate_of_project_id) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'DUPLICATE_OF_PROJECT_ID', 'UPDATE', OLD.duplicate_of_project_id, NEW.duplicate_of_project_id, statement_timestamp(), l_changed_by);
       end if;

       -- PRIORITY_ID
       if not sp_value_compare.is_equal(OLD.priority_id,NEW.priority_id) then
          for c1 in (SELECT 'P'||PRIORITY r from SP_PROJECT_PRIORITIES x where x.id = OLD.PRIORITY_ID) loop l_old_value := c1.r;end loop;
          for c1 in (SELECT 'P'||PRIORITY r from SP_PROJECT_PRIORITIES x where x.id = NEW.PRIORITY_ID) loop l_new_value := c1.r;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'PRIORITY', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       -- RELEASE_ID
       if not sp_value_compare.is_equal(OLD.RELEASE_ID,NEW.RELEASE_ID) then
          for c1 in (SELECT RELEASE_TRAIN||' '||RELEASE r from SP_RELEASE_TRAINS x where x.id = OLD.RELEASE_ID) loop l_old_value := c1.r;end loop;
          for c1 in (SELECT RELEASE_TRAIN||' '||RELEASE r from SP_RELEASE_TRAINS x where x.id = NEW.RELEASE_ID) loop l_new_value := c1.r;end loop;
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'RELEASE', 'UPDATE', l_old_value, l_new_value, statement_timestamp(), l_changed_by);
       end if;
       -- TAGS
       if not sp_value_compare.is_equal(OLD.tags,NEW.tags) then
          insert into sp_project_history(project_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
          values (NEW.id, 'TAGS', 'UPDATE', OLD.tags, NEW.tags, statement_timestamp(), l_changed_by);
