CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_release_milestones_biu() RETURNS trigger AS $BODY$
declare
    l_tags        varchar(4000) := null;
    l_changed_by  varchar(255)  := null;
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
        if coalesce(NEW.original_milestone_date::text, '') = '' then
            NEW.original_milestone_date := NEW.milestone_date;
        end if;
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    NEW.upper_milestone_name := upper(NEW.milestone_name);

    --
    -- adjust tag data
    --
    if (NEW.tags IS NOT NULL AND NEW.tags::text <> '') then
        l_tags := trim(both upper(NEW.tags));
        -- remove multiple spaces
        if position('  ' in l_tags) > 0 then
            for j in 1..10 loop
                l_tags := replace(l_tags,'  ',' ');
                if position('  ' in l_tags) = 0 then
                   exit;
                end if;
            end loop;
        end if;
        for i in 1..length(l_tags) loop
            if i > 2 and substr(l_tags,i,1) = ' ' and substr(l_tags,i-1,1) != ',' then
               l_tags := substr(l_tags,1,i-1)||'-'||substr(l_tags,i+1);
            end if;
        end loop;
        NEW.tags := l_tags;
   end if;

    --
    -- touch parent table
    --
    update sp_release_trains set updated = statement_timestamp(), updated_by = NEW.updated_by where id = NEW.release_id;

    --
    -- change history tracking
    --
    if TG_OP = 'INSERT' then
        insert into sp_release_history(release_id, attribute_column, change_type, new_value, changed_on, changed_by)
        values (NEW.release_id, 'RELEASE_MILESTONE', 'CREATE', NEW.milestone_name, statement_timestamp(), lower(NEW.created_by));
    elsif TG_OP = 'UPDATE' then
        l_changed_by := lower(NEW.updated_by);
        --
        if not sp_value_compare.is_equal(OLD.milestone_name,NEW.milestone_name) then
           insert into sp_release_history(release_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
           values (NEW.release_id, 'RELEASE_MILESTONE', 'UPDATE', OLD.milestone_name, NEW.milestone_name, statement_timestamp(), l_changed_by);
        end if;
        --
        if not sp_value_compare.is_equal(OLD.milestone_start_date,NEW.milestone_start_date) then
           insert into sp_release_history(release_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
           values (NEW.release_id, 'RELEASE_MILESTONE_'||substr(NEW.milestone_name,1,200)||'_START', 'UPDATE', to_char(OLD.milestone_start_date,'DD-MON-YYYY'), to_char(NEW.milestone_start_date,'DD-MON-YYYY'), statement_timestamp(), l_changed_by);
        end if;
        --
        if not sp_value_compare.is_equal(OLD.milestone_date,NEW.milestone_date) then
           insert into sp_release_history(release_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
           values (NEW.release_id, 'RELEASE_MILESTONE_'||substr(NEW.milestone_name,1,235), 'UPDATE', to_char(OLD.milestone_date,'DD-MON-YYYY'), to_char(NEW.milestone_date,'DD-MON-YYYY'), statement_timestamp(), l_changed_by);
        end if;
            --
        if not sp_value_compare.is_equal(OLD.MILESTONE_COMPLETED_YN,NEW.MILESTONE_COMPLETED_YN) then
           insert into sp_release_history(release_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
           values (NEW.release_id, 'RELEASE_MILESTONE_'||substr(NEW.milestone_name,1,225)||'_COMPLETED', 'UPDATE', OLD.MILESTONE_COMPLETED_YN, NEW.MILESTONE_COMPLETED_YN, statement_timestamp(), l_changed_by);
        end if;
        -- 
        if not sp_value_compare.is_equal(OLD.tags,NEW.tags) then
           insert into sp_release_history(release_id, attribute_column, change_type, old_value, new_value, changed_on, changed_by)
           values (NEW.release_id, 'RELEASE_MILESTONE_'||substr(NEW.milestone_name,1,225)||'_TAGS', 'UPDATE', OLD.TAGS, NEW.TAGS, statement_timestamp(), l_changed_by);
        end if;
    end if;
RETURN NEW;
end
$BODY$
 LANGUAGE 'plpgsql';

