DROP TRIGGER IF EXISTS sp_activity_types_biu ON sp_activity_types CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_activity_types_biu() RETURNS trigger AS $BODY$
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    --
    if coalesce(NEW.is_active_yn::text, '') = '' then
       NEW.is_active_yn := 'Y';
    end if;
    --
    -- history
    --
    if TG_OP = 'INSERT' then
        insert into sp_app_log(activity, details)
        values ('Added Activity Type' , NEW.activity_type);
    elsif TG_OP = 'UPDATE' then
        if not sp_value_compare.is_equal(OLD.activity_type,NEW.activity_type) then
            insert into sp_app_log(activity, details)
            values ('Updated Activity Type' , 'Changed "'||OLD.activity_type ||'" to "'||NEW.activity_type||'"');
        end if;
        if not sp_value_compare.is_equal(OLD.STATIC_ID,NEW.STATIC_ID) then
            insert into sp_app_log(activity, details)
            values ('Updated Activity Type' , NEW.activity_type||': changed STATIC_ID from "'||OLD.STATIC_ID||'" to "'||NEW.STATIC_ID||'"');
        end if;
        if not sp_value_compare.is_equal(OLD.IS_PROJECT_YN,NEW.IS_PROJECT_YN) then
            insert into sp_app_log(activity, details)
            values ('Updated Activity Type' , NEW.activity_type||': changed IS_PROJECT from "'||OLD.IS_PROJECT_YN||'" to "'||NEW.IS_PROJECT_YN||'"');
        end if;
        if not sp_value_compare.is_equal(OLD.IS_DEFAULT_YN,NEW.IS_DEFAULT_YN) then
            insert into sp_app_log(activity, details)
            values ('Updated Activity Type' , NEW.activity_type||': changed IS_DEFAULT from "'||OLD.IS_DEFAULT_YN||'" to "'||NEW.IS_DEFAULT_YN||'"');
        end if;
        if not sp_value_compare.is_equal(OLD.IS_ACTIVE_YN,NEW.IS_ACTIVE_YN) then
            insert into sp_app_log(activity, details)
            values ('Updated Activity Type' , NEW.activity_type||': changed IS_ACTIVE from "'||OLD.IS_ACTIVE_YN||'" to "'||NEW.IS_ACTIVE_YN||'"');
        end if;
    end if;
RETURN NEW;
end
$BODY$
 LANGUAGE 'plpgsql';

