DECLARE
  c1 RECORD;
    l_old_value   varchar(4000) := null;
    l_new_value   varchar(4000) := null;
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    --
    -- touch parent table
    --
    update sp_initiatives set updated = statement_timestamp(), updated_by = NEW.updated_by where id = NEW.initiative_id;
    --
    -- history
    --
    if TG_OP = 'INSERT' then
        for c1 in (SELECT approval_type r from sp_approval_types x where x.id = NEW.approval_type_id) loop l_new_value := c1.r;end loop;
        insert into sp_initiative_history(initiative_id, attribute_column, change_type, new_value, changed_on, changed_by) 
        values 
            (NEW.initiative_id, 'INITIATIVE_APPROVAL', 'CREATE', l_new_value||' ('||(case when NEW.active_yn = 'Y' then 'Active' else 'Inactive' end)||')', statement_timestamp(), lower(NEW.created_by));
    elsif TG_OP = 'UPDATE' then
        if not sp_value_compare.is_equal(OLD.approval_type_id,NEW.approval_type_id) or
           not sp_value_compare.is_equal(OLD.active_yn,NEW.active_yn) then
            for c1 in (SELECT approval_type r from sp_approval_types x where x.id = OLD.approval_type_id) loop l_old_value := c1.r;end loop;
            for c1 in (SELECT approval_type r from sp_approval_types x where x.id = NEW.approval_type_id) loop l_new_value := c1.r;end loop;
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values
                (NEW.initiative_id, 'INITIATIVE_APPROVAL', 'UPDATE', 
                 l_old_value||' ('||(case when OLD.active_yn = 'Y' then 'Active' else 'Inactive' end)||')', 
                 l_new_value||' ('||(case when NEW.active_yn = 'Y' then 'Active' else 'Inactive' end)||')', 
                 statement_timestamp(), lower(NEW.updated_by));
        end if;
    end if;
RETURN NEW;
end
