DROP TRIGGER IF EXISTS sp_initiative_approval_chain_biu ON sp_initiative_approval_chain CASCADE;
CREATE OR REPLACE FUNCTION legacy.trigger_fct_sp_initiative_approval_chain_biu() RETURNS trigger AS $BODY$
DECLARE
  c1 RECORD;
    l_initiative_id  numeric;
    l_approval_type  varchar(4000) := null;
    l_old_value      varchar(4000) := null;
    l_new_value      varchar(4000) := null;
BEGIN
    if TG_OP = 'INSERT' then
        NEW.created := statement_timestamp();
        NEW.created_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    end if;
    NEW.updated := statement_timestamp();
    NEW.updated_by := coalesce(sys_context('APEX$SESSION','APP_USER'),user);
    --
    NEW.alternate_start_date := date_trunc('day', NEW.alternate_start_date);
    NEW.alternate_end_date   := date_trunc('day', NEW.alternate_end_date);
    --
    -- touch parent table
    --
    update sp_initiative_approvals set updated = statement_timestamp(), updated_by = OLD.updated_by where id = OLD.initiative_approval_id;
    --
    -- history
    --
    if TG_OP = 'INSERT' then
        for c1 in (SELECT x.initiative_id, t.approval_type
                     from sp_initiative_approvals x, sp_approval_types t 
                    where x.id = NEW.initiative_approval_id
                      and x.approval_type_id = t.id
                  ) loop l_initiative_id := c1.initiative_id;l_approval_type := c1.approval_type;end loop;
        for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = NEW.team_member_id) loop l_new_value := NEW.approval_seq||'-'||c1.r;end loop;
        insert into sp_initiative_history(initiative_id, attribute_column, change_type, new_value, changed_on, changed_by)
        values (l_initiative_id, 'INITIATIVE_APPROVAL_CHAIN', 'CREATE', l_approval_type||' - '||l_new_value, statement_timestamp(), lower(NEW.created_by));
    elsif TG_OP = 'UPDATE' then
        if not sp_value_compare.is_equal(OLD.team_member_id,NEW.team_member_id) or
               sp_value_compare.is_equal(OLD.approval_seq,NEW.approval_seq) or
               sp_value_compare.is_equal(OLD.active_yn,NEW.active_yn) or
               sp_value_compare.is_equal(OLD.alternate_team_member_id,NEW.alternate_team_member_id) or
               sp_value_compare.is_equal(OLD.alternate_start_date,NEW.alternate_start_date) or
               sp_value_compare.is_equal(OLD.alternate_end_date,NEW.alternate_end_date)
        then
            for c1 in (SELECT x.initiative_id, t.approval_type 
                         from sp_initiative_approvals x, sp_approval_types t 
                        where x.id = NEW.initiative_approval_id
                          and x.approval_type_id = t.id
                      ) loop l_initiative_id := c1.initiative_id;l_approval_type := c1.approval_type;end loop;
            for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = OLD.team_member_id) loop l_old_value := OLD.approval_seq||'-'||c1.r;end loop;
            for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = NEW.team_member_id) loop l_new_value := NEW.approval_seq||'-'||c1.r;end loop;
            if sp_value_compare.is_equal(OLD.alternate_team_member_id,NEW.alternate_team_member_id) then
                for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = OLD.alternate_team_member_id) loop
                           l_old_value := l_old_value || ' [alternate '||c1.r||' '||(case when (OLD.alternate_start_date IS NOT NULL AND OLD.alternate_start_date::text <> '') then OLD.alternate_start_date||' thru ' end)|| 
                                                                                    (case when (OLD.alternate_end_date IS NOT NULL AND OLD.alternate_end_date::text <> '') then OLD.alternate_end_date end)||']';end loop;
                for c1 in (SELECT lower(email) r from SP_TEAM_MEMBERS x where x.id = NEW.alternate_team_member_id) loop
                           l_new_value := l_new_value || ' [alternate '||c1.r||' '||(case when (NEW.alternate_start_date IS NOT NULL AND NEW.alternate_start_date::text <> '') then NEW.alternate_start_date||' thru ' end)|| 
                                                                                    (case when (NEW.alternate_end_date IS NOT NULL AND NEW.alternate_end_date::text <> '') then NEW.alternate_end_date end)||']';end loop;
            end if;
            insert into sp_initiative_history(initiative_id, attribute_column, change_type, old_value, new_value,changed_on, changed_by)
            values (l_initiative_id, 'INITIATIVE_APPROVAL_CHAIN', 'UPDATE',
                 l_approval_type||' - '||l_old_value||' ('||CASE WHEN OLD.active_yn='Y' THEN 'Active'  ELSE 'Inactive' END ||')', 
                 l_approval_type||' - '||l_new_value||' ('||CASE WHEN NEW.active_yn='Y' THEN 'Active'  ELSE 'Inactive' END ||')', 
                 statement_timestamp(), lower(NEW.updated_by));
        end if;
    end if;
RETURN NEW;
end
$BODY$
 LANGUAGE 'plpgsql';

